"""Compact campaign view hosted by the existing standard-library local app."""
MOC_HTML = r"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>MoC continuation · BO-ICL</title>
<style>
:root{font-family:Segoe UI,system-ui,sans-serif;color:#142d36;background:#f3f6f6}*{box-sizing:border-box}body{max-width:1180px;margin:auto;padding:28px}h1{font-size:28px;margin:4px 0}h2{font-size:19px;margin-top:0}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.sub{color:#536a73;font-size:14px}section{background:white;border:1px solid #dbe4e4;border-radius:12px;padding:22px;margin-bottom:18px}.row{display:flex;align-items:end;gap:14px;flex-wrap:wrap}.row>label{flex:1;min-width:160px}label{display:block;font-size:13px;font-weight:600;margin:8px 0}input,select,textarea,button{font:inherit}input,select,textarea{display:block;width:100%;padding:10px;border:1px solid #b8c9ce;border-radius:6px;margin-top:5px;background:#fff;color:#142d36}button,.button{padding:10px 16px;background:#087e80;border:0;border-radius:6px;color:white;cursor:pointer;display:inline-block;text-decoration:none}button.secondary{background:#e4eeee;color:#163d46}button:disabled{opacity:.5;cursor:default}.badge{padding:5px 10px;border-radius:15px;background:#e3f2ed;font-size:12px;display:inline-block}.warning{background:#fff1cf;padding:12px;border-radius:6px}.stats{display:flex;gap:36px;flex-wrap:wrap;margin:16px 0}.stats b{display:block;font-size:26px}.stats span{font-size:13px;color:#50676f}details{margin-top:18px}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:14px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{text-align:left;border-bottom:1px solid #dde5e6;padding:9px}#notice{position:sticky;top:8px;z-index:1;background:#edf7f7;border:1px solid #b9d8d8;padding:12px;border-radius:6px;margin-bottom:16px}#notice:empty{display:none}.hidden{display:none!important}.layout{display:grid;grid-template-columns:1.3fr 1fr;gap:18px}textarea{min-height:110px}.muted{color:#61757b}.recipe{font-size:14px;line-height:1.6}.values{display:flex;gap:22px;flex-wrap:wrap;margin:12px 0}a{color:#087e80}@media(max-width:960px){.layout{grid-template-columns:1fr}body{padding:15px}}
</style><header><div><span class="sub">BO-ICL · LOCAL CAMPAIGNS</span><h1>MoC continuation</h1><div class="sub">Suggest an experiment. Record its measured result. Continue.</div></div><a id="mainView" href="/">Main toolkit interface →</a></header>
<div id="notice" role="status"></div><div id="demo" class="warning hidden">SYNTHETIC DEMONSTRATION — provider responses and any new measurements are demonstration fixtures. No model API calls.</div>
<section><h2>1 · Campaign and data</h2><div class="row"><label>Saved campaign<select id="campaign"><option value="">Create or resume a campaign</option></select></label><button class="secondary" id="resume">Resume</button><button class="secondary" id="openCampaignTab">Open selected in new tab</button><a id="export" class="button" href="#">Export bundle</a><label>Import saved bundle<input id="bundleFile" type="file" accept=".json"></label></div>
<details id="checkpointPanel" class="hidden"><summary>Saved checkpoints</summary><p class="sub">Changes save automatically. Resume a checkpoint as an independent campaign copy with its measurements, settings and pending reservations.</p><div class="row"><label>Checkpoint label (optional)<input id="checkpointName"></label><button class="secondary" id="saveCheckpoint">Save checkpoint now</button></div><label>Saved point<select id="checkpointSelect"></select></label><div class="row"><button class="secondary" id="refreshCheckpoints">Refresh list</button><button id="restoreCheckpoint">Resume selected as independent copy</button></div></details>
<details id="createPanel" open><summary>Load MoC continuation package</summary><p class="sub">The included source data contains 7,776 recipes and the confirmed M7, M12, M13 observations. Optionally select the supplied workbook; its named sheets are validated together. Import makes no model calls.</p><div class="row"><label>Method preset<select id="preset"><option value="moc_llm">Matched LLM replicate</option><option value="moc_gp">Structured GP continuation</option><option value="moc_embedding_gp">Embedding GP baseline</option><option value="moc_eight">Eight-observation LLM history</option></select></label><label>New-measurement budget<input id="budget" type="number" min="0" placeholder="No limit"></label><label>Optional source workbook<input type="file" id="workbook" accept=".xlsx"></label></div><div class="row"><button id="create">Load campaign</button><button class="secondary" id="pair">Create matched GP + LLM campaigns</button></div></details></section>
<div id="active" class="hidden"><section><div class="row"><h2>2 · Method</h2><span id="engine" class="badge"></span><span id="campaignIdentity" class="sub"></span></div><div id="stats" class="stats"></div><p id="stage"></p><div class="row"><label>Primary method<select id="method"><option value="llm">BO-ICL (LLM)</option><option value="gp">Gaussian process</option></select></label><label>Refresh suggestion after saving a measurement<input id="auto" type="checkbox" style="width:auto"></label></div>
<details id="settingsPanel"><summary>Advanced settings and effective configuration</summary><div id="gpSettings"><label>GP input representation<select id="representation"><option value="gpr_features">Synthesis parameters</option><option value="gpr_embeddings">Text embeddings</option></select></label><p id="gpExplain" class="sub"></p></div><div id="llmSettings"><div class="row"><label>Prediction model<input id="forwardModel"></label><label>Inverse model<input id="inverseModel"></label><label>Predictions per candidate<input id="samples" type="number" min="2"></label></div><div class="row"><label>Observed examples<select id="examples"><option value="nearest">Nearest observed (up to five)</option><option value="all">All observed examples</option></select></label><label>Uncertainty multiplier<input id="scalar" type="number" min="0" step=".1"></label></div><p class="sub">One inverse query per step, one completion per query. Nearest 100 eligible recipes → MMR 16 → five forward predictions. EI is in percentage points. An automatic target uses best + max(0, multiplier − 1) × |best|, bounded to 0–100.</p><label>Custom prediction system message (blank uses managed prompt)<textarea id="forwardPrompt"></textarea></label><label>Custom inverse system message (blank uses managed prompt)<textarea id="inversePrompt"></textarea></label></div><button class="secondary" id="previewSettings">Preview settings changes</button><pre id="configPreview"></pre><button id="applySettings" class="hidden">Apply reviewed settings</button><details><summary>Resolved settings</summary><pre id="resolved"></pre></details></details></section>
<section><h2>Live progress</h2><p class="sub">The main toolkit graph shows human-guided initialization at step 0, subsequent measured outcomes, pending predictions, and selected independent comparison traces.</p><iframe id="sharedGraph" title="Shared campaign live graph" style="width:100%;height:440px;border:0;border-radius:8px" loading="lazy"></iframe></section><div class="layout"><section><h2>3 · Suggest experiment</h2><div class="row"><button id="suggest">Start suggestion</button><button class="secondary" id="cancelJob">Cancel current work</button></div><p id="progress" role="status" class="sub"></p><div id="proposal"></div><details id="cachePanel"><summary>Embedding cache transfer</summary><p class="sub">Import a safe cache package from a local folder, or prepare only missing vectors. Preparing embeddings is an intentional live API action. Structured GP needs none.</p><label>Cache package folder<input id="cachePath" placeholder="Absolute local folder containing manifest.json"></label><div class="row"><button class="secondary" id="cacheImport">Validate and import cache</button><button class="secondary" id="cachePrepare">Prepare missing embeddings</button></div><pre id="cacheReport"></pre></details></section>
<section><h2>4 · Record measurement</h2><p class="sub">Reserve a recommendation, perform and measure the synthesis, then enter the actual result. A prediction never becomes a measurement automatically.</p><label>Pending experiment<select id="pending"></select></label><label>Measured MoC (wt%)<input id="value" type="number" min="0" max="100" step="any"></label><details id="measurementQuality"><summary>Measurement quality</summary><div class="row"><label>XRD esd (percentage points)<input id="sigma" type="number" min="0" step="any"></label><label>GOF<input id="gof" type="number" min="0" step="any"></label><label>Closure gap (percentage points)<input id="gap" type="number" step="any"></label></div><label>Gap source / override reason<input id="gapOrigin" placeholder="Required; distinguish an override from a computed gap"></label><div class="row"><label>Mo (wt%, optional)<input id="moPhase" type="number" min="0" max="100" step="any"></label><label>Mo2C (wt%, optional)<input id="mo2cPhase" type="number" min="0" max="100" step="any"></label><label>MoO2 (wt%, optional)<input id="moo2Phase" type="number" min="0" max="100" step="any"></label></div><label>Reported phase accounting is complete<input id="phasesComplete" type="checkbox" style="width:auto"></label></details><label>Measurement note<input id="note"></label><div class="row"><button id="measure">Save confirmed measurement</button><button id="release" class="secondary">Release reservation</button></div></section></div>
<section><h2>5 · History and provenance</h2><div id="history"></div><details><summary>Source decisions and excluded historical measurements</summary><p>M12 = <strong>83.8 wt%</strong>, confirmed on 20 September 2026. The older 81.7 value is superseded provenance. Source gap overrides remain zero; M12's phase accounting residual is −0.3 points. Missing metadata is never a measured zero.</p><p id="policy"></p><pre id="provenance"></pre></details><details><summary>Exact requests, prediction samples, targets and replay</summary><label>Recorded suggestion<select id="replayStep"></select></label><button class="secondary" id="replay">Replay recorded step offline</button><pre id="replayResult"></pre></details><details><summary>Revise a measurement refinement</summary><p class="sub">This retains the physical measurement ID and preserves the old refinement as superseded. Use the measurement fields above for its revised values.</p><label>Observation<select id="reviseObservation"></select></label><label>Revision reason<input id="revisionReason"></label><button class="secondary" id="revise">Save refinement revision</button></details></section></div>
<script>
const $=id=>document.getElementById(id);let current=new URLSearchParams(location.search).get('campaign')||localStorage.getItem('boicl_shared_campaign_id')||'',state=null,poll=null,settings=null,settingsCampaign=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function fmt(v){return typeof v==='number'&&Number.isFinite(v)?v.toFixed(2):'—';}
function targetHtml(t){if(!t)return '';return `<p><b>Inverse target:</b> best ${fmt(t.best)}; multiplier ${fmt(t.multiplier_draw)}; raw ${fmt(t.raw_target)} → resolved ${fmt(t.resolved_target)} wt%.</p><details><summary>Target calculation and bounds</summary><pre>${esc(JSON.stringify(t,null,2))}</pre></details>`;}
function predictionHtml(r){const p=r.prediction;if(!p)return '<p>No model prediction is attached to this selection.</p>';let text=`<p><b>Predicted MoC:</b> ${fmt(p.mean)} wt%</p>`;if(p.lower95!=null)text+=`<p><b>95% latent-function interval:</b> ${fmt(p.lower95)}–${fmt(p.upper95)} wt%</p>`;if(p.accepted_samples!=null)text+=`<p><b>Accepted predictions:</b> ${p.accepted_samples} / ${p.requested_samples??state.config.llm.n_samples}. ${p.partial_samples?'Partial sample set. ':''}${p.std===0?'Agreement among responses; this does not establish accuracy.':'Completion spread: '+fmt(p.std)+' percentage points.'}</p>`;text+=`<p><b>Acquisition:</b> ${fmt(r.score)} ${esc(r.acquisition_units||'')}</p>`;text+=`<details><summary>Prediction diagnostics</summary><pre>${esc(JSON.stringify(p,null,2))}</pre></details>`;return text;}
async function api(action,body={},method='POST'){const r=await fetch('/api/moc/'+action,{method,headers:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
function notice(t){$('notice').textContent=t;}async function guarded(fn){try{await fn();}catch(e){notice(e.message);if(/esd|sigma|gof|gap|quality/i.test(e.message))$('measurementQuality').open=true;}}
async function catalog(){const r=await api('list',{},'GET');r.campaigns=r.campaigns.filter(c=>c.data_schema!=='generic');$('demo').classList.toggle('hidden',!r.demo);$('campaign').innerHTML='<option value="">Select a saved campaign</option>'+r.campaigns.map(c=>`<option value="${esc(c.campaign_id)}">${esc(c.name)} · ${esc(c.campaign_id.slice(0,8))}${c.selection_policy==='random_control'?' · RANDOM CONTROL':''}${c.synthetic_demo?' · DEMO':''}</option>`).join('');if(current&&r.campaigns.some(c=>c.campaign_id===current))$('campaign').value=current;else current='';}
function toggle(){const llm=$('method').value==='llm';$('llmSettings').classList.toggle('hidden',!llm);$('gpSettings').classList.toggle('hidden',llm);$('cachePanel').classList.toggle('hidden',!llm&&$('representation').value==='gpr_features');$('gpExplain').textContent=$('representation').value==='gpr_features'?'Six fixed synthesis features. Matérn 5/2 ARD, quality-dependent observation noise, bounded posterior. No credentials or embeddings.':`Procedure-only ${state?.config.embedding_gp.embedding_model||'text-embedding-ada-002'} embeddings, fixed full-corpus Isomap, learned homoskedastic noise; a distinct baseline.`;}
async function load(){if(!current)return;const requested=current;localStorage.setItem('boicl_shared_campaign_id',requested);history.replaceState(null,'','/moc?campaign='+encodeURIComponent(requested));$('mainView').href='/?campaign='+encodeURIComponent(requested);const loaded=await api('state?id='+encodeURIComponent(requested),{},'GET');if(requested!==current)return;state=loaded;if($('checkpointPanel').dataset.campaign!==current){settings=null;settingsCampaign=null;$('applySettings').classList.add('hidden');$('configPreview').textContent='';for(const field of ['value','sigma','gof','gap','gapOrigin','moPhase','mo2cPhase','moo2Phase','note','revisionReason'])$(field).value='';$('phasesComplete').checked=false;$('pending').innerHTML='';$('checkpointPanel').open=false;$('checkpointPanel').dataset.campaign=current;$('checkpointSelect').innerHTML='';}$('checkpointPanel').classList.remove('hidden');render();}
function render(){const s=state,c=s.config;$('active').classList.remove('hidden');$('createPanel').open=false;$('engine').textContent=c.selection_policy==='random_control'?'Independent random control':s.engine_label;$('campaignIdentity').textContent=c.name+' · '+s.campaign_id;$('export').href='/api/moc/export?id='+current;$('stats').innerHTML=[['Measured',s.counts.measured],['Pending',s.counts.pending],['Available',s.counts.available],['Best measured',s.best==null?'—':s.best+' wt%']].map(([k,v])=>`<div><b>${esc(v)}</b><span>${k}</span></div>`).join('');$('stage').textContent=c.selection_policy==='random_control'?'Uniform random selection; only this independent arm’s confirmed measurements enter its history.':c.engine==='gpr_features'?(s.counts.unique_measured<c.structured_gp.ei_after_unique_measured_designs?`Space-filling: ${s.counts.unique_measured} of ${c.structured_gp.ei_after_unique_measured_designs} measured designs. Selection seeks coverage.`:`Expected improvement across all eligible designs; xi ${c.structured_gp.ei_xi_standardized_logit} standardized logit units.`):'Full eligible pool; '+(c.engine==='llm'?c.llm.acquisition.replaceAll('_',' ')+' from the empirical completion distribution.':'latent-function EI, in raw objective units.');$('method').value=c.engine==='llm'?'llm':'gp';$('representation').value=c.engine==='gpr_embeddings'?'gpr_embeddings':'gpr_features';$('auto').checked=c.auto_suggest;$('forwardModel').value=c.llm.forward_model;$('inverseModel').value=c.llm.inverse_model;$('samples').value=c.llm.n_samples;$('scalar').value=c.llm.uncertainty_scalar;$('examples').value=c.llm.selector_mode;$('forwardPrompt').value=c.llm.forward_system_message||'';$('inversePrompt').value=c.llm.inverse_system_message||'';$('resolved').textContent=JSON.stringify(c,null,2);const graphKey=current+':'+s.history_revision+':'+s.counts.pending+':'+s.suggestions.length;if($('sharedGraph').dataset.key!==graphKey){$('sharedGraph').src='/campaign-graph?campaign='+encodeURIComponent(current);$('sharedGraph').dataset.key=graphKey;}toggle();$('progress').textContent=s.progress?.status?`${s.progress.status}: ${s.progress.detail||''}`:'';$('suggest').disabled=s.progress?.status==='running';
const latest=[...s.suggestions].reverse().find(x=>x.status==='suggested'||x.status==='pending');$('proposal').innerHTML=latest?`<hr><span class="badge">${esc(latest.status)}${latest.planned_quality_repeat?' · planned quality repeat':''}</span><h3>${esc(latest.candidate_id)}</h3><p><b>Selection reason:</b> ${esc(latest.selection_reason)}</p><p class="recipe">${esc(latest.candidate.procedure)}</p><div class="values">${[['temperature_C','Temperature (°C)'],['ramp_C_per_min','Ramp (°C/min)'],['gas','Gas'],['flow_sccm','Flow (sccm)'],['hold_h','Hold (h)'],['sucrose_to_AMT_mass_ratio','Sucrose:AMT']].map(([k,label])=>`<span>${label}: <b>${esc(latest.candidate[k])}</b></span>`).join('')}</div>${targetHtml(latest.inverse_target)}${predictionHtml(latest)}${latest.status==='suggested'?`<button onclick="reserve('${latest.suggestion_id}')">Reserve this experiment</button>`:''}`:'<p class="muted">Start a suggestion to choose an eligible recipe.</p>';
const previousPending=$('pending').value;$('pending').innerHTML=s.suggestions.filter(r=>r.status==='pending').map(r=>`<option value="${r.suggestion_id}">${esc(r.candidate_id)}</option>`).join('');if(previousPending)$('pending').value=previousPending;$('measure').disabled=!$('pending').value;$('release').disabled=!$('pending').value;$('history').innerHTML='<table><thead><tr><th>Run / measurement</th><th>MoC wt%</th><th>XRD esd</th><th>GOF</th><th>Gap</th><th>Status</th></tr></thead><tbody>'+s.observations.map(o=>`<tr><td>${esc(o.run_id||o.observation_id.slice(0,12))}${o.synthetic?' · synthetic':''}</td><td>${o.moc_wt_pct}</td><td>${o.moc_wt_pct_sigma??'unknown'}</td><td>${o.gof??'unknown'}</td><td>${o.closure_gap_wt_pct??'unknown'}</td><td>${esc(o.record_status)}</td></tr>`).join('')+'</tbody></table>';$('provenance').textContent=JSON.stringify({resolution:s.provenance.m12_resolution,archived:s.archive.map(o=>({id:o.observation_id,value:o.moc_wt_pct,excluded:!o.training_included,phase_residual:o.phase_accounting_residual_wt_pct}))},null,2);$('policy').textContent='Repeat policy: '+c.repeat_policy+'. '+(c.initialization==='eight_observations'?'The five historical measurements are included in this explicitly selected eight-observation initialization.':'Five archived measurements remain known history and are excluded from the matched models.')+' Later histories are independent.';$('replayStep').innerHTML=s.suggestions.map(r=>`<option value="${r.suggestion_id}">${esc(r.candidate_id||r.status)} · ${esc(r.status)}</option>`).join('');$('reviseObservation').innerHTML=s.observations.filter(o=>o.record_status==='measured').map(o=>`<option value="${o.observation_id}">${esc(o.run_id||o.observation_id)}</option>`).join('');if(s.progress?.status==='running'){clearTimeout(poll);poll=setTimeout(()=>guarded(load),1000);}}
async function create(pair){const file=$('workbook').files[0];let workbook=null;if(file){const buf=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buf.length;i+=32768)binary+=String.fromCharCode(...buf.subarray(i,i+32768));workbook=btoa(binary);}const r=await api(pair?'pair':'create',{preset:$('preset').value,workbook,budget:$('budget').value===''?null:Number($('budget').value)});current=pair?r.gp:r.campaign_id;await catalog();await load();notice(pair?'Created independent matched campaigns. Choose either in Saved campaign.':'Validated 7,776 candidates and initialized live measurements. No model calls.');}
async function loadCheckpoints(){if(!current)return;const requested=current,previous=$('checkpointSelect').value;const result=await api('checkpoints?id='+encodeURIComponent(requested),{},'GET');if(requested!==current)return;$('checkpointSelect').innerHTML=result.checkpoints.map(r=>`<option value="${esc(r.checkpoint_id)}">${esc(r.created_at)} · ${esc(r.name||r.reason||'Saved point')} · ${r.observation_count} measured / ${r.pending_count} pending</option>`).join('');if(result.checkpoints.some(r=>r.checkpoint_id===previous))$('checkpointSelect').value=previous;$('restoreCheckpoint').disabled=!result.checkpoints.length;}
$('openCampaignTab').onclick=()=>guarded(async()=>{const id=$('campaign').value;if(!id)throw Error('Select a saved campaign first.');window.open('/moc?campaign='+encodeURIComponent(id),'_blank','noopener');});$('checkpointPanel').ontoggle=()=>{if($('checkpointPanel').open)guarded(loadCheckpoints);};$('refreshCheckpoints').onclick=()=>guarded(loadCheckpoints);$('saveCheckpoint').onclick=()=>guarded(async()=>{await api('checkpoint',{id:current,name:$('checkpointName').value||null});await loadCheckpoints();notice('Checkpoint saved.');});$('restoreCheckpoint').onclick=()=>guarded(async()=>{const checkpoint_id=$('checkpointSelect').value;if(!checkpoint_id)throw Error('Select a saved checkpoint.');const result=await api('restore-checkpoint',{id:current,checkpoint_id});current=result.campaign_id;await catalog();await load();notice('Opened an independent campaign copy from the selected checkpoint.');});
$('create').onclick=()=>guarded(()=>create(false));$('pair').onclick=()=>guarded(()=>create(true));$('resume').onclick=()=>guarded(async()=>{current=$('campaign').value;await load();notice('Campaign resumed with measurements and pending reservations preserved.');});$('suggest').onclick=()=>guarded(async()=>{await api('suggest',{id:current});await load();});$('cancelJob').onclick=()=>guarded(async()=>{await api('cancel',{id:current});await load();});window.reserve=id=>guarded(async()=>{await api('reserve',{id:current,suggestion_id:id});await load();});$('release').onclick=()=>guarded(async()=>{await api('release',{id:current,suggestion_id:$('pending').value});await load();});
function values(){return {moc_wt_pct:$('value').value,moc_wt_pct_sigma:$('sigma').value,gof:$('gof').value,closure_gap_wt_pct:$('gap').value,closure_gap_origin:$('gapOrigin').value,source_note:$('note').value,mo_wt_pct:$('moPhase').value,mo2c_wt_pct:$('mo2cPhase').value,moo2_wt_pct:$('moo2Phase').value,phase_accounting_complete:$('phasesComplete').checked};}
$('measure').onclick=()=>guarded(async()=>{await api('measure',{id:current,suggestion_id:$('pending').value,values:values(),request_id:crypto.randomUUID()});await load();notice('Measurement saved atomically with its quality metadata.');});$('revise').onclick=()=>guarded(async()=>{await api('refine',{id:current,observation_id:$('reviseObservation').value,values:values(),reason:$('revisionReason').value});await load();notice('New refinement saved; old record retained and previous suggestions invalidated.');});function methodChanged(){toggle();$('settingsPanel').open=true;$('suggest').disabled=true;notice('Preview and apply the changed method before starting a suggestion.');}$('method').onchange=methodChanged;$('representation').onchange=methodChanged;$('auto').onchange=()=>{ $('settingsPanel').open=true;notice('Preview and apply this setting to save the refresh preference.');};
$('previewSettings').onclick=()=>guarded(async()=>{const requested=current;settingsCampaign=requested;settings={engine:$('method').value==='llm'?'llm':$('representation').value,auto_suggest:$('auto').checked,llm:{...state.config.llm,forward_model:$('forwardModel').value,inverse_model:$('inverseModel').value,n_samples:Number($('samples').value),uncertainty_scalar:Number($('scalar').value),selector_mode:$('examples').value,selector_k:state.config.llm.selector_k??5,forward_system_message:$('forwardPrompt').value===(state.config.llm.forward_system_message??'')?state.config.llm.forward_system_message:$('forwardPrompt').value,inverse_system_message:$('inversePrompt').value===(state.config.llm.inverse_system_message??'')?state.config.llm.inverse_system_message:$('inversePrompt').value}};const r=await api('config-preview',{id:requested,changes:settings});if(requested!==current)return;$('configPreview').textContent=JSON.stringify(r.after,null,2);$('applySettings').classList.remove('hidden');});$('applySettings').onclick=()=>guarded(async()=>{if(!settings||settingsCampaign!==current)throw Error('Preview settings for the active campaign before applying them.');await api('config',{id:current,changes:settings});$('applySettings').classList.add('hidden');await load();notice('Settings saved. Unreserved suggestions are superseded; measurements and custom prompts are retained.');});
$('bundleFile').onchange=()=>guarded(async()=>{const file=$('bundleFile').files[0];if(!file)return;const r=await api('import',{bundle_json:await file.text()});current=r.campaign_id;await catalog();await load();notice('Portable campaign restored.');});$('replay').onclick=()=>guarded(async()=>{const r=await api('replay',{id:current,suggestion_id:$('replayStep').value});$('replayResult').textContent=JSON.stringify(r,null,2);});$('cacheImport').onclick=()=>guarded(async()=>{const r=await api('cache-import',{id:current,path:$('cachePath').value});$('cacheReport').textContent=JSON.stringify(r,null,2);});$('cachePrepare').onclick=()=>guarded(async()=>{await api('cache-prepare',{id:current});await load();notice('Preparing missing embeddings. Progress is shown above.');});guarded(async()=>{await catalog();if(current)await load();});
</script></html>"""
